import sys

def max_profit_brute(prices):
    n = len(prices)
    best = 0
    for i in range(n):
        for j in range(i + 1, n):
            if prices[j] - prices[i] > best:
                best = prices[j] - prices[i]
    return best

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    prices = list(map(int, data[1:1 + n]))
    print(max_profit_brute(prices))
